parameters.jsCode:
const skills = $input.item.json.skills;

let lines = ['📋 *Your Skills Master List*\n'];

for (const [category, items] of Object.entries(skills)) {
  lines.push(`*${category}*`);
  lines.push(items.map(i => `  • ${i}`).join('\n'));
  lines.push('');
}

return [{ json: { text: lines.join('\n') } }];

const data = $input.item.json;
let lines = ['📂 *Your Resume Entries*\n'];

lines.push('*💼 Experience*');
for (const e of data.experience_entries || []) {
  lines.push(`  • *Role:* ${e.title}`);
  lines.push(`     *Company:* ${e.company}`);
  lines.push(`     *Date:* ${e.dates}`);
  lines.push(`     *ID:* \`${e.id}\``);
}

lines.push('');
lines.push('*🛠 Projects*');
for (const p of data.project_entries || []) {
  lines.push(`  • *Name:* ${p.name}`);
  lines.push(`     *Tech:* ${p.tech_stack}`);
  lines.push(`     *Date:* ${p.dates}`);
  lines.push(`     *ID:* \`${p.id}\``);
}

lines.push('');
lines.push('*🏅 Leadership*');
for (const l of data.leadership || []) {
  lines.push(`  • *Title:* ${l.title}`);
  lines.push(`     *Org:* ${l.org}`);
  lines.push(`     *Date:* ${l.dates}`);
}

lines.push('\n_Use /listfacts <ID> to see bullets for any entry._');
lines.push('');

return [{ json: { text: lines.join('\n') } }];

const data = $input.item.json;
const entryId = $('ID Check').first().json.body;

if (data.count === 0) {
  return [{ json: { text: `⚠️ No facts found for entry ID: \`${entryId}\`\n\nUse /listentries to see valid IDs.` } }];
}

let lines = [`📝 *Facts for* \`${entryId}\` (${data.count} bullet${data.count > 1 ? 's' : ''})\n`];

for (const fact of data.facts) {
  lines.push(`*ID:* \`${fact.id}\``);
  lines.push(`• ${fact.text}`);
  if (fact.tech_tags.length > 0) {
    lines.push(`_Tags: ${fact.tech_tags.join(', ')}_`);
  }
  lines.push('');
}

return [{ json: { text: lines.join('\n') } }];

const h = $input.item.json.header;
const lines = [
  '👤 *Your Profile*\n',
  `*Name:* ${h.name}`,
  `*Phone:* ${h.phone}`,
  `*Email:* ${h.email}`,
  `*LinkedIn:* ${h.linkedin_url}`,
  `*GitHub:* ${h.github_url}`,
  '',
  '_Use /setname, /setphone, /setemail, /setlinkedin, /setgithub to update any field._'
];
return [{ json: { text: lines.join('\n') } }];

const command = $json.command;
const body = $json.body.trim();
const fieldMap = {
  '/setname': 'name',
  '/setphone': 'phone',
  '/setemail': 'email',
  '/setlinkedin': 'linkedin_url',
  '/setgithub': 'github_url'
};
const field = fieldMap[command];
if (!field || !body) {
  return [{ json: { error: true, text: '⚠️ Usage: ' + command + ' <value>' } }];
}
return [{ json: { patch: { [field]: body }, field } }];

const edu = $input.item.json.education || [];
const lines = ['🎓 *Education Entries*\n'];
for (const e of edu) {
  lines.push(`*${e.institution}*`);
  lines.push(`  ${e.degree_line}`);
  lines.push(`  ${e.dates}`);
  lines.push(`  ID: \`${e.id}\``);
  if (e.courses && e.courses.length > 0) {
    lines.push(`  Courses (${e.courses.length}): ${e.courses.slice(0, 3).join(', ')}${e.courses.length > 3 ? '...' : ''}`);
  }
  lines.push('');
}
lines.push('_Use /addcourse <id> <name> or /deletecourse <id> <name>_');
return [{ json: { text: lines.join('\n') } }];

const parts = $json.body.split(' ');
const edu_id = parts[0];
const course = parts.slice(1).join(' ');
return [{ json: { edu_id, course } }];

const parts = $json.body.split(' ');
const edu_id = parts[0];
const course = parts.slice(1).join(' ');
return [{ json: { edu_id, course } }];

const parts = $json.body.split(' ');
const fact_id = parts[0];
const new_text = parts.slice(1).join(' ');
return [{ json: { fact_id, new_text } }];

